const items = $input.all();

const flattened = items.map(item => {
  const inquiry = item.json;
  return {
    json: {
      inquiryId: inquiry.inquiryId,
      clientName: inquiry.client.name,
      clientEmail: inquiry.client.email,
      clientPhone: inquiry.client.phone,
      propertyTitle: inquiry.property.title,
      propertyArea: inquiry.property.area,
      askingPrice: inquiry.property.askingPrice,
      bedrooms: inquiry.property.bedrooms,
      contactMethod: inquiry.preferences.contactMethod,
      urgency: inquiry.preferences.urgency
    }
  };
});

return flattened;

const items = $input.all();

const summaries = items.map(item => {
  const inquiry = item.json;
  const message = `📩 New Inquiry: ${inquiry.clientName}
🏠 ${inquiry.propertyTitle} (${inquiry.propertyArea})
💰 Asking Price: QAR ${inquiry.askingPrice.toLocaleString()}
📞 Prefers: ${inquiry.contactMethod} | Urgency: ${inquiry.urgency}`;

  return { json: { message } };
});

return summaries;

const items = $input.all();

console.log("DEBUG - number of items:", items.length);
console.log("DEBUG - first item json:", JSON.stringify(items[0].json));

const totalValue = items.reduce((sum, item) => {
  console.log("DEBUG - askingPrice:", item.json.askingPrice);
  return sum + item.json.askingPrice;
}, 0);

const averageValue = totalValue / items.length;

const report = {
  totalInquiries: items.length,
  totalAskingValue: totalValue,
  averageAskingPrice: Math.round(averageValue)
};

return [{ json: report }];
